  "onb.profile.counterOn": "Se envía a api.harness-maxxing.com. Tu seudónimo y tu idioma solo se envían junto con un correo electrónico. Un contador anónimo (versión, sistema, códigos de estado; sin nombre ni IP) está activado por defecto: puedes desactivarlo en Ajustes → Perfil.",
  "register.desc": "Todo es opcional. Lo que este servidor cuenta a los autores de Harness Maxxing y cómo detenerlo.",
