  "register.news": "Enviarme también las novedades del producto",
  "register.newsDesc": "Nuevas funciones, unas pocas veces al mes como máximo. Puedes darte de baja aquí en cualquier momento.",
  "register.count": "Ayudar a contar las instalaciones (anónimo)",
  "register.countDesc": "Una vez al día: un número aleatorio, la versión, el sistema (p. ej. Ubuntu 24.04, x86_64) y algunos códigos de estado (servicio activo, Claude conectado, última actualización fallida…). Sin nombre, sin correo, sin IP, sin nombre de servidor, sin contenido.",
  "register.countBlocked": "Desactivado en este servidor por MAXXING_NO_TELEMETRY o DO_NOT_TRACK en el entorno del servicio.",
  "register.privacy": "Se envía a api.harness-maxxing.com. Tu seudónimo y tu idioma solo se envían junto con un correo electrónico. Si desmarcas todo, se detiene todo: no volveremos a contactar con este servidor.",
  "register.statusOff": "Este servidor no cuenta nada a los autores.",
