  "claude.tabSubscription": "Suscripción de Claude",
  "claude.tabApiKey": "Clave de API",
  "claude.subscriptionIntro": "Recomendado con un plan Pro, Max o Ultra. Genera un token de larga duración desde este servidor (Claude Code ya está instalado allí):",
