  "claude.authFailed": "Claude ha rechazado estas credenciales.",
  "claude.connectTest": "Conectar y probar",
  "claude.testing": "Enviando un mensaje de prueba a Claude…",
  "cdef.defaultModel": "Modelo predeterminado",
  "cdef.cliDefault": "Predeterminado de Claude Code",
  "cdef.defaultModelHint": "Las sesiones muestran el modelo que realmente respondió en cada turno.",
  "cdef.autoCompact": "Compactación automática",
  "cdef.autoCompactHint": "Cuando un turno termina con más contexto que este umbral, Harness resume la sesión y continúa en un hilo nuevo que parte de ese resumen (como Compactar): las sesiones largas dejan de reenviar todo su historial, lo que ahorra tokens. El historial sigue visible.",
  "cdef.autoCompactOff": "Desactivada",
  "cdef.autoCompactRecommended": "recomendado",
  "cdef.idleCompact": "Compactar al volver",
  "cdef.idleCompactHint": "La caché de prompts de Claude dura unos minutos (una hora como máximo). Cuando escribes en una sesión inactiva desde hace más tiempo, con al menos este contexto, Harness primero la resume y tu mensaje se ejecuta en un hilo nuevo que parte de ese resumen: el historial se reenviaría a precio completo de todos modos, así que los turnos siguientes cuestan mucho menos. Cuesta un turno de resumen (una breve espera) antes de la respuesta.",
  "cdef.smartResume": "Reanudación inteligente",
  "cdef.smartResumeHint": "Cuando vuelves a una sesión cuya caché ha caducado (ver arriba) con al menos este contexto, o tras 5 minutos o más con el doble, Harness hace que Claude resuma primero la sesión para el mensaje que acabas de enviar: el resumen conserva exactamente lo que tu mensaje necesita (archivos, comandos, valores, el plan en curso) y después tu mensaje se ejecuta en un hilo nuevo, mucho más ligero. Medido en reanudaciones reales: entre un 38 y un 67 % menos de tokens a partir de 100k, y los detalles se conservan mejor que con el resumen simple. Desactivado = solo la regla anterior.",
  "cdef.protectSecrets": "Proteger los secretos",
  "cdef.protectSecretsHint": "Las herramientas de Claude se niegan a leer o editar los secretos del servidor (secrets.json) y las claves SSH (~/.ssh), sea cual sea el modo de permisos. Evita que una instrucción oculta en una página web o un correo los lea sin más; un script escrito para abrir el archivo no se bloquea: para contenido externo, prefiere un modo de permisos más estricto en ese tema.",
  "cdef.shortTitles": "Títulos de sesión cortos",
  "cdef.shortTitlesHint": "Una sesión nueva se nombra con pocas palabras a partir de su primer mensaje (sin saludos ni «¿puedes…?»). Desactivado: el título es el inicio del mensaje. Renombrar una sesión siempre tiene prioridad.",
  "cdef.shortTitlesModel": "Títulos escritos por Claude",
  "cdef.shortTitlesModelHint": "El modelo más pequeño nombra el tema (títulos más acertados). Una llamada rápida por cada sesión nueva, contada en tu plan de Claude.",
  "pbox.mode": "Sandbox (solo este tema)",
  "pbox.modeDesc": "Claude trabaja libremente dentro de la carpeta del tema, sin preguntar: sus comandos solo escriben ahí y no pueden leer las claves del servidor ni la carpeta personal. Lo que tenga que salir de ahí (instalar un paquete, reiniciar un servicio, otra carpeta) te lo pregunta antes, con un botón que da acceso completo al tema.",
  "cdef.autoUpdate": "Actualizar Claude Code automáticamente",
  "cdef.autoUpdateHint": "Desactivado por defecto. Activado: cuando sale una versión estable más reciente de Claude Code (ya usada durante algunos días, no la última de todas), el servidor la instala en cuanto no se haya ejecutado nada durante 10 minutos (ningún turno, ningún mensaje en cola, ninguna tarea programada) y vuelve a la anterior si no arranca. Se comprueba cada 6 horas; el resultado aparece en las notificaciones.",
  "cdef.autoUpdateLast": "Última actualización: {from} → {to}, {date}",
  "cdef.autoUpdateFailed": "Error al actualizar a {to} ({date})",
  "claude.permissionMode": "Modo de permisos",
  "claude.mode.bypass": "Acceso completo (permisos omitidos)",
  "claude.mode.bypassDesc": "Claude ejecuta cualquier comando y edita cualquier archivo sin preguntar, con los derechos del usuario del servicio (root). Elígelo solo si este servidor está dedicado a Claude.",
  "claude.mode.recommendedVps": "Solo VPS dedicado",
  "claude.mode.acceptEdits": "Aceptar ediciones de archivos",
  "claude.mode.acceptEditsDesc": "Claude puede leer y escribir archivos; las demás herramientas que requieren aprobación (la mayoría de los comandos de shell) se rechazan.",
  "claude.mode.default": "Estricto (rechazar)",
  "claude.mode.defaultDesc": "Toda herramienta que requiere aprobación se rechaza sin preguntar. Lo más seguro, pero Claude puede hacer mucho menos.",
  "claude.mode.ask": "Preguntarme",
  "claude.mode.askDesc": "Leer es libre; todo lo demás espera tu Permitir o Denegar, en la sesión, en las notificaciones o en Telegram. Se deniega tras 30 min sin respuesta.",
