  "mcp.whatTitle": "Los servidores MCP dan nuevas herramientas a Claude",
  "mcp.whatExplain": "Un servidor añadido para «Todas las sesiones» está disponible en todas partes; si se añade a un tema, solo en las sesiones de ese tema. Los secretos se quedan en Ajustes → Claves y se escriben ${KEY_NAME}. También puedes pedírselo a Claude en un tema: «conecta el MCP …».",
