  "mcp.auto": "Cargar los servidores MCP solo cuando una sesión los necesite",
  "mcp.autoHint": "Cada servidor cargado consume tokens en cada mensaje y ralentiza el inicio de un turno. Si se activa, una sesión recibe los servidores que su tema ya usó, los nombrados en tu mensaje y los añadidos a su tema; Claude puede pedir otro (`maxxing mcp load`) y Harness continúa por sí mismo. Si hace falta un conector de claude.ai, se carga todo, como antes. Las herramientas del Navegador de Harness y de tus Dispositivos siempre están disponibles cuando un turno puede usarlas.",
