  "infra.how.create": "En cualquier sesión, di lo que quieres: Claude sigue las recetas estándar (un sitio detrás de Caddy con HTTPS, una base de datos PostgreSQL con copia de seguridad cada noche, un bucket S3) y lo nuevo aparece aquí. Abre cualquier línea para ver sus detalles o preguntarle a Claude.",
  "infra.how.createTitle": "Creas pidiéndoselo a Claude",
  "infra.how.watch": "Se comprueba cada dirección (si responde, si su certificado es válido), así como la caducidad de los dominios y el espacio en disco. Un problema sube al principio de esta página y a tus notificaciones, una vez por incidente.",
  "infra.how.watchTitle": "Lo vigila por ti",
  "infra.how.read": "Este servidor directamente, tus otros servidores por SSH (solo lectura), y Cloudflare y Hostinger con sus claves de API. Lista cada sitio, base de datos, bucket, dominio y servidor, y los vincula entre sí (un dominio con su sitio, un sitio con su app, su base de datos y su repositorio git).",
  "infra.how.readTitle": "Harness lo lee todo",
