  "infra.mail.f.dmarc_inherited_sp": "Cuando SPF y DKIM pasen para {domain}, cambia sp=none por sp=quarantine y después por sp=reject en el registro de {parent}, o dale a {domain} su propio registro _dmarc.{domain} con p=quarantine. No rebajes el p= de {parent}.",
