  "infra.mail.f.dmarc_inherited_sp_quarantine": "Para que {domain} también tenga p={parent_policy}, cambia sp={policy} por sp={parent_policy} (o quita sp=) en el registro de {parent}, o dale a {domain} su propio registro _dmarc.{domain} con p={parent_policy}. No rebajes el p= de {parent}.",
