  "infra.mail.p.no_spf_unknown": "Sin registro SPF: cualquiera puede hacerse pasar por @{domain} al enviar correo.",
  "infra.mail.f.no_spf_unknown": "Añade en {domain} un registro TXT que nombre cada servicio con el que envías correo. Solo a partir de sus registros MX sería {record}: añade el include: del servicio con el que envías (tu proveedor de correo lo documenta) antes de ~all, o el correo que envíes fallará en SPF.",
  "system.health": "Estado",
  "system.healthDesc": "Se actualiza cada 30 segundos.",
