  "system.cleanup": "Liberar espacio",
  "system.cleanupClaude": "Limpiar con Claude",
  "system.cleanupDesc": "Solo lo que vuelve por sí solo o lo que tú elijas. Los proyectos, los adjuntos y los renderizados se quedan: Limpiar con Claude los revisa contigo.",
