  "system.cleanup.leftovers": "Versiones antiguas y restos",
  "system.cleanup.leftoversDesc": "Versiones anteriores de los componentes, navegadores que ya no se usan, archivos temporales, registros demasiado grandes.",
  "system.cleanup.caches": "Cachés de descarga",
  "system.cleanup.cachesDesc": "Cachés de uv, npm, pip y npx: se vuelven a descargar la próxima vez que hagan falta. Lo que usa una herramienta en ejecución se conserva.",
  "system.cleanup.journal": "Registros del sistema",
  "system.cleanup.journalDesc": "El journal de systemd, reducido a sus últimos 200 MB.",
  "system.cleanup.apt": "Paquetes del sistema descargados",
  "system.cleanup.aptDesc": "Paquetes que apt ya instaló (apt-get clean).",
  "system.cleanup.previews": "Vistas previas de vídeo y miniaturas",
  "system.cleanup.previewsDesc": "Copias ligeras de los vídeos para el reproductor y miniaturas de archivos: se vuelven a crear al mostrarse (algo de CPU). Un vídeo reproducido hace menos de 30 min se conserva.",
  "system.cleanup.trash": "Papelera de Harness",
  "system.cleanup.trashDesc": "Temas, sesiones y archivos eliminados: después ya no se podrán restaurar.",
  "system.cleanupPrompt": "Haz una auditoría del espacio en disco de este servidor y ayúdame a liberarlo correctamente.\n\n1. Estado: `df -h` y `free -h`, luego las carpetas más grandes (`du -xh --max-depth=2 / 2>/dev/null | sort -h | tail -40`), y profundiza en las más grandes. Ajustes -> Sistema -> Liberar espacio ya se ocupa de las cachés de descarga, las versiones antiguas de los componentes, el journal del sistema, los paquetes apt, las vistas previas de vídeo y la papelera de Harness: déjalos de lado.\n2. Recorre cada proyecto y tema del espacio de trabajo: adjuntos, renderizados de vídeo y audio, exportaciones, `node_modules`, entornos de Python, builds, repositorios git pesados, copias separadas olvidadas, duplicados. Mira también las cachés de otras herramientas (`~/.cache/*`, modelos descargados), los registros y los archivos viejos de `/tmp`.\n3. Para cada elemento grande, averigua de dónde viene: qué proyecto, herramienta o tarea programada lo creó (fechas, contenido, memoria del tema, crons) y si sigue creciendo.\n4. Dame una tabla ordenada por tamaño: ruta, tamaño, origen, si vuelve por sí solo o no, lo que propones (eliminar, mover a otro sitio, conservar) y el espacio que se libera.\n5. No elimines nada sin mi visto bueno: hazme todas tus preguntas de una vez. Para lo que vuelve una y otra vez, propón corregir la causa (un límite de tamaño, una limpieza en el script o la tarea que lo produce).\n6. Al final, anota en la memoria del tema adecuado lo que hemos decidido (lo que se conserva, lo que se limpia).",
